using System.Runtime.CompilerServices;
using System.Text.Json;
using System.Text.RegularExpressions;
using Bellatrix.Cli;
using Bellatrix.Execution;
using Bellatrix.Execution.Mobile;
using Bellatrix.Execution.Snapshots;
using Xunit;

namespace Bellatrix.Cli.Tests;

/// <summary>
/// Conformance fixtures (<c>tests/fixtures/snapshots/</c>).
/// <list type="bullet">
/// <item>Synthetic desktop/Android fixtures are GENERATED by the production parsers from the committed page-source XML
/// (<c>BELLATRIX_UPDATE_FIXTURES=1</c> regenerates), so key presence, skip rules and ControlType are exactly what a
/// live snapshot would contain. Without the variable the committed JSON must equal the parser output.</item>
/// <item>Every answer-key target resolves through the REAL <c>bellatrix &lt;domain&gt; find --snapshot</c> to exactly
/// one node, and every expected locator selects that node and only that node in the fixture.</item>
/// </list>
/// </summary>
public class FixtureTests
{
    public static readonly TheoryData<string> Fixtures = new() { "desktop-calculator", "web-demo-shop", "android-apidemos" };

    public static TheoryData<string, string> Targets()
    {
        var data = new TheoryData<string, string>();
        foreach (var fixture in new[] { "desktop-calculator", "web-demo-shop", "android-apidemos" })
        {
            foreach (var target in LoadKey(fixture).GetProperty("targets").EnumerateArray())
            {
                data.Add(fixture, target.GetProperty("id").GetString()!);
            }
        }

        return data;
    }

    [Theory]
    [InlineData("desktop-calculator")]
    [InlineData("android-apidemos")]
    public void SyntheticFixture_EqualsProductionParserOutput(string fixture)
    {
        var key = LoadKey(fixture);
        Assert.True(key.GetProperty("synthetic").GetBoolean(), "only synthetic fixtures are generated from XML");

        var xml = File.ReadAllText(Path.Combine(Dir(), key.GetProperty("source").GetString()!));
        var nodes = key.GetProperty("domain").GetString() == "desktop"
            ? DesktopService.ParsePageSource(xml)
            : MobileService.ParsePageSource(xml);
        Assert.NotEmpty(nodes);

        // Serialize through the production writer (SnapshotStore.Save), exactly like `snapshot` does.
        var temp = Path.Combine(Path.GetTempPath(), "bellatrix-fixture-" + Guid.NewGuid().ToString("N"));
        try
        {
            var generated = File.ReadAllText(new SnapshotStore(temp).Save(fixture, nodes).Path);
            var fixturePath = Path.Combine(Dir(), fixture + ".json");
            if (Environment.GetEnvironmentVariable("BELLATRIX_UPDATE_FIXTURES") == "1")
            {
                File.WriteAllText(fixturePath, generated);
            }

            Assert.True(File.Exists(fixturePath), $"{fixture}.json missing; run with BELLATRIX_UPDATE_FIXTURES=1");
            Assert.Equal(generated, File.ReadAllText(fixturePath).Replace("\r\n", "\n").TrimEnd('\n'));
        }
        finally
        {
            try { Directory.Delete(temp, true); } catch { /* best effort */ }
        }
    }

    [Fact]
    public void SyntheticDesktopFixture_DropsNamelessChrome_AndKeepsControlType()
    {
        var nodes = new SnapshotStore().Load(Path.Combine(Dir(), "desktop-calculator.json"));

        Assert.All(nodes, n => Assert.True(n.ContainsKey("ControlType")));
        Assert.DoesNotContain(nodes, n => n["Tag"].ToString() == "Pane" && !n.ContainsKey("Name") && !n.ContainsKey("AutomationId"));
        Assert.Contains(nodes, n => n.TryGetValue("IsEnabled", out var e) && e.ToString() == "False"); // disabled memory buttons
        Assert.Contains(nodes, n => n.TryGetValue("IsOffscreen", out var o) && o.ToString() == "True");
    }

    [Theory]
    [MemberData(nameof(Fixtures))]
    public void AnswerKey_IsWellFormed(string fixture)
    {
        var key = LoadKey(fixture);
        Assert.Equal(fixture + ".json", key.GetProperty("fixture").GetString());
        Assert.Contains(key.GetProperty("domain").GetString(), new[] { "desktop", "web", "mobile" });
        Assert.Equal(5, key.GetProperty("targets").GetArrayLength());
        Assert.True(File.Exists(Path.Combine(Dir(), fixture + ".json")));
    }

    [Theory]
    [MemberData(nameof(Targets))]
    public void Target_ResolvesViaRealFind_ToExactlyOneNode_MatchedByEveryExpectedLocator(string fixture, string targetId)
    {
        var key = LoadKey(fixture);
        var domain = key.GetProperty("domain").GetString()!;
        var target = key.GetProperty("targets").EnumerateArray().Single(t => t.GetProperty("id").GetString() == targetId);
        var path = Path.Combine(Dir(), fixture + ".json");

        var args = new List<string> { domain, "find", "--snapshot", path };
        args.AddRange(target.GetProperty("findArgs").EnumerateArray().Select(a => a.GetString()!));
        args.Add("--json");
        var (exit, stdout) = Capture(() => CliRunner.Run(args.ToArray()));

        Assert.Equal(0, exit);
        using var result = JsonDocument.Parse(stdout);
        Assert.Equal(1, result.RootElement.GetProperty("count").GetInt32());
        var found = ToDictionary(result.RootElement.GetProperty("nodes")[0]);

        var all = new SnapshotStore().Load(path).Select(n => n.ToDictionary(kv => kv.Key, kv => kv.Value?.ToString() ?? "")).ToList();
        foreach (var locator in target.GetProperty("expected").EnumerateArray().Select(e => e.GetString()!))
        {
            var predicate = LocatorMatcher.Parse(domain, locator);
            Assert.True(predicate(found), $"[{fixture}/{targetId}] '{locator}' does not select the node find returned");
            Assert.True(all.Count(predicate) == 1, $"[{fixture}/{targetId}] '{locator}' selects {all.Count(predicate)} nodes, expected exactly 1");
        }
    }

    private static Dictionary<string, string> ToDictionary(JsonElement node)
        => node.EnumerateObject().ToDictionary(p => p.Name, p => p.Value.ValueKind == JsonValueKind.String ? p.Value.GetString()! : p.Value.ToString());

    private static JsonElement LoadKey(string fixture)
        => JsonDocument.Parse(File.ReadAllText(Path.Combine(Dir(), fixture + ".answers.json"))).RootElement.Clone();

    private static string Dir([CallerFilePath] string thisFile = "")
        => Path.GetFullPath(Path.Combine(Path.GetDirectoryName(thisFile)!, "..", "fixtures", "snapshots"));

    private static (int exit, string stdout) Capture(Func<int> run)
    {
        var original = Console.Out;
        using var writer = new StringWriter();
        Console.SetOut(writer);
        try
        {
            return (run(), writer.ToString());
        }
        finally
        {
            Console.SetOut(original);
        }
    }
}

/// <summary>
/// The minimal locator forms the answer keys use, evaluated against snapshot nodes: XPath <c>//tag[@a='v' and …]</c>
/// with <c>text()</c>/<c>normalize-space()</c>, CSS <c>#id</c>, <c>tag.class</c>, <c>tag[a='v']</c>, and (mobile) a
/// bare accessibility id. An unsupported form fails the test, so keys stay checkable.
/// </summary>
internal static class LocatorMatcher
{
    private static readonly Regex XPath = new(@"^//(?<tag>[\w.*-]+)\[(?<preds>.+)\]$");
    private static readonly Regex Pred = new(@"^(?:@(?<attr>[\w-]+)|(?<fn>text\(\)|normalize-space\((?:\.)?\)))\s*=\s*'(?<val>[^']*)'$");
    private static readonly Regex Css = new(@"^(?<tag>[\w-]+)?(?:#(?<id>[\w-]+)|\.(?<cls>[\w-]+)|\[(?<attr>[\w-]+)='(?<val>[^']*)'\])?$");

    public static Func<Dictionary<string, string>, bool> Parse(string domain, string locator)
    {
        var m = XPath.Match(locator);
        if (m.Success)
        {
            var tag = m.Groups["tag"].Value;
            var checks = new List<Func<Dictionary<string, string>, bool>> { n => TagMatches(domain, n, tag) };
            foreach (var part in m.Groups["preds"].Value.Split(" and "))
            {
                var p = Pred.Match(part.Trim());
                Assert.True(p.Success, $"unsupported XPath predicate '{part}' in '{locator}'");
                var value = p.Groups["val"].Value;
                if (p.Groups["fn"].Success)
                {
                    var trim = p.Groups["fn"].Value.StartsWith("normalize-space", StringComparison.Ordinal);
                    checks.Add(n => Equal(trim ? Norm(TextOf(domain, n)) : TextOf(domain, n), value));
                }
                else
                {
                    var keyName = Key(domain, p.Groups["attr"].Value);
                    checks.Add(n => Equal(n.GetValueOrDefault(keyName), value));
                }
            }

            return n => checks.All(c => c(n));
        }

        if (domain == "web")
        {
            var c = Css.Match(locator);
            Assert.True(c.Success, $"unsupported CSS '{locator}'");
            var tag = c.Groups["tag"].Value;
            return n =>
                (tag.Length == 0 || TagMatches(domain, n, tag))
                && (!c.Groups["id"].Success || Equal(n.GetValueOrDefault("Id"), c.Groups["id"].Value))
                && (!c.Groups["cls"].Success || (n.GetValueOrDefault("Class") ?? "").Split(' ').Contains(c.Groups["cls"].Value))
                && (!c.Groups["attr"].Success || Equal(n.GetValueOrDefault(Key(domain, c.Groups["attr"].Value)), c.Groups["val"].Value));
        }

        Assert.True(domain == "mobile" && !locator.StartsWith('/'), $"unsupported locator '{locator}' for {domain}");
        return n => Equal(n.GetValueOrDefault("ContentDesc"), locator); // Android accessibility id = content-desc
    }

    private static bool TagMatches(string domain, Dictionary<string, string> n, string tag)
        => tag == "*" || domain switch
        {
            "desktop" => Equal(n.GetValueOrDefault("ControlType"), tag) || Equal(n.GetValueOrDefault("Tag"), tag),
            "mobile" => Equal(n.GetValueOrDefault("Class"), tag),
            _ => Equal(n.GetValueOrDefault("Tag"), tag),
        };

    private static string? TextOf(string domain, Dictionary<string, string> n)
        => domain == "desktop" ? n.GetValueOrDefault("Name") : n.GetValueOrDefault("Text");

    private static string Key(string domain, string attr) => (domain, attr.ToLowerInvariant()) switch
    {
        ("desktop", _) => attr, // UIA attribute names are the snapshot keys (AutomationId, Name, ClassName, …)
        ("web", "aria-label") => "AriaLabel",
        ("web", "data-testid") => "DataTestid",
        ("mobile", "resource-id") => "ResourceId",
        ("mobile", "content-desc") => "ContentDesc",
        (_, var a) => char.ToUpperInvariant(a[0]) + a[1..],
    };

    private static string? Norm(string? s) => s is null ? null : Regex.Replace(s.Trim(), @"\s+", " ");

    private static bool Equal(string? a, string b) => a is not null && string.Equals(a, b, StringComparison.Ordinal);
}
